class Solution {
public:
    int nearestValidPoint(int x, int y, vector<vector<int>>& points) {
        int bestDist = INT_MAX;
        int bestIdx = -1;
        for (int i = 0; i < (int)points.size(); i++) {
            int a = points[i][0];
            int b = points[i][1];
            if (a == x || b == y) {
                int d = abs(x - a) + abs(y - b);
                if (d < bestDist) {
                    bestDist = d;
                    bestIdx = i;
                }
            }
        }
        return bestIdx;
    }
};
